function setbackStatus(rule){return {conditional:'Regra documental · enquadramento informado',document:'Documento informado · não validado',pending:'Enquadramento pendente',demonstration:'Premissa de demonstração'}[rule.status]||'Pendente'}
function setbackSummary(rule=calc().setbackRule){const v=rule.top.values;return `${rule.resolved?'Recuos do último pavimento':'Prévia demonstrativa'}: frente ${number(v.front,2)} m · laterais ${number(v.side,2)} m · fundos ${number(v.back,2)} m.`}
function setbackSource(rule){return rule.source?`<p class="setback-source">Base: ${rule.source.url?`<a href="${esc(rule.source.url)}" target="_blank" rel="noopener noreferrer">${esc(rule.source.title)}</a>`:esc(rule.source.title)}${rule.catalog?' · '+esc(rule.catalog.pages):''}</p>`:''}
function setbackRulesForm(){
 const context=state.lot.urbanContext||{},g=getLotGeometry(),mode=context.mode||'catalog',rule=calc().setbackRule;
 const selected=(a,b)=>a===b?'selected':'';
 const field=(name,label,value)=>`<label class="setback-field" for="setback-${name}">${label}<input id="setback-${name}" name="${name}" inputmode="decimal" value="${esc(value??'')}" placeholder="metros"></label>`;
 return `<form id="setback-rule-form"><div class="setback-form-grid"><label class="setback-field" for="setback-mode">Origem dos recuos<select id="setback-mode" name="mode"><option value="catalog" ${selected(mode,'catalog')}>Legislação de João Pessoa · regra geral</option><option value="manual" ${selected(mode,'manual')}>Valores de um documento ou certidão</option><option value="demo" ${selected(mode,'demo')}>Somente demonstração</option></select></label><label class="setback-field" for="setback-zone">Zona do terreno<select id="setback-zone" name="zone"><option value="">Selecione a zona</option>${SetbackRules.zones.map(zone=>`<option value="${zone}" ${selected(context.zone,zone)}>${zone}</option>`).join('')}<option value="other" ${selected(context.zone,'other')}>Outra zona / não identificada</option></select></label><label class="setback-field" for="setback-coastal">Faixa de orla (500 m)<select id="setback-coastal" name="coastal"><option value="">Não verificada</option><option value="outside" ${selected(context.coastal,'outside')}>Fora da faixa, conforme informação do lote</option><option value="inside" ${selected(context.coastal,'inside')}>Dentro da faixa / incidência possível</option></select></label><label class="setback-field" for="setback-regime">Condições de aplicação<select id="setback-regime" name="regime"><option value="">Não verificadas</option><option value="ordinary" ${selected(context.regime,'ordinary')}>Construção convencional, sem regimes especiais</option><option value="special" ${selected(context.regime,'special')}>Há regime especial ou preciso verificar</option></select></label></div><p class="setback-help">A zona deve vir de consulta cadastral ou certidão; o bairro ou um ponto no mapa não confirmam o zoneamento. O catálogo inicial cobre ZH1 a ZH5. Pavimentos incluem o térreo.</p><details class="setback-frontages"><summary>Confrontações com ruas e rodovias</summary><p>Marque cada lado que faz frente para uma via. Em esquina, todas as frentes recebem recuo frontal.</p>${g.vertices.map((_,i)=>`<div class="setback-edge-input"><label><input type="checkbox" name="street-${i}" ${i===g.front||(context.streetEdges||[]).includes(i)?'checked':''} ${i===g.front?'disabled':''}>Lado ${i+1} · ${esc(ParcelGeometry.label(g,i))}</label><select name="road-${i}" aria-label="Tipo de via do lado ${i+1}"><option value="urban" ${selected(context.roads?.[i]||'urban','urban')}>Via urbana</option><option value="highway" ${selected(context.roads?.[i],'highway')}>Rodovia</option></select></div>`).join('')}</details><details class="setback-manual" ${mode==='manual'?'open':''}><summary>Valores e referência do documento</summary><p>Preencha se escolher “Valores de um documento ou certidão”. Nesta opção, os valores são constantes em todos os pavimentos.</p><div class="setback-manual-grid">${field('front','Frente (m)',context.front)}${field('side','Laterais (m)',context.side)}${field('back','Fundos (m)',context.back)}</div><label class="setback-field" for="setback-reference">Certidão, norma ou documento de referência<input id="setback-reference" name="reference" maxlength="250" value="${esc(context.reference||'')}" placeholder="Número, órgão e data do documento"></label><label class="setback-field" for="setback-reference-url">Link do documento (opcional)<input id="setback-reference-url" name="url" type="url" value="${esc(context.url||'')}" placeholder="https://..."></label></details><p class="setback-current-status" role="status">${esc(setbackStatus(rule))}. ${esc(rule.reason)}</p><button class="btn primary" type="submit">${icon('check')}Aplicar recuos ao estudo e ao 3D</button></form>`;
}
function setbackPanel(){
 const c=calc(),r=c.setbackRule;
 return `<section class="setback-panel panel" aria-labelledby="setback-title"><div class="setback-panel-heading"><div><div class="eyebrow">TERRENO · LEGISLAÇÃO · GEOMETRIA</div><h2 id="setback-title">Recuos para construir</h2></div><span class="setback-status ${r.resolved?'ready':''}">${esc(setbackStatus(r))}</span></div><p class="setback-intro">Defina o enquadramento para aplicar os afastamentos da construção às divisas do terreno.</p>${setbackRulesForm()}${setbackSource(r)}<p class="setback-help">${esc(r.warnings.join(' '))}</p></section>`;
}
function setbackModelSummary(){
 const c=calc(),r=c.setbackRule,v=r.top.values;
 return `<section class="setback-model-summary" aria-label="Recuos aplicados ao modelo"><div><strong>${r.resolved?'Recuos no modelo 3D':'Recuos ilustrativos no 3D'}</strong><span>${esc(setbackStatus(r))}${r.zone?' · '+esc(r.zone):''}</span></div><div class="setback-values"><span>Frente <b>${number(v.front,2)} m</b></span><span>Laterais <b>${number(v.side,2)} m</b></span><span>Fundos <b>${number(v.back,2)} m</b></span></div><p>Valores do último pavimento. As linhas do envelope e a massa acompanham os recuos de cada pavimento.</p>${c.envelope.method==='conservative_uniform'?`<p>Aproximação geométrica: recuo uniforme de ${number(c.envelope.uniform,2)} m no térreo, por concavidade ou fundos indefinidos.</p>`:''}${btn('Recuos e legislação','book','setback-rules','wide')}${setbackSource(r)}</section>`;
}
function openSetbackRules(){modal('Recuos e legislação',setbackRulesForm().replace(/(id|for)="setback-/g,'$1="dialog-setback-')+setbackSource(calc().setbackRule),'',true);$('.modal').classList.add('setback-modal');$('.modal-backdrop').classList.add('setback-backdrop')}
function setbackReport(){
 const c=calc(),r=c.setbackRule,g=getLotGeometry();
 return `<div class="report-block setback-report"><h3>Recuos, enquadramento e fontes</h3><p>${esc(setbackStatus(r))}. ${esc(r.reason)}</p><p>Zona informada: ${esc(r.zone||'Não identificada')}. Município: João Pessoa/PB.</p><table class="compare-table" aria-label="Recuos por pavimento"><thead><tr><th>Pavimento</th><th>Frente principal</th><th>Laterais</th><th>Fundos</th></tr></thead><tbody>${r.levels.map(level=>`<tr><td>${level.floor===1?'1 · térreo':level.floor}</td><td>${number(level.values.front,2)} m</td><td>${number(level.values.side,2)} m</td><td>${number(level.values.back,2)} m</td></tr>`).join('')}</tbody></table> <table class="compare-table" aria-label="Recuos por lado do terreno"><thead><tr><th>Lado</th><th>Classificação</th><th>Recuo no último pavimento</th></tr></thead><tbody>${r.top.edges.map(edge=>`<tr><td>${edge.index+1}</td><td>${esc(edge.role)}</td><td>${number(edge.distance,2)} m</td></tr>`).join('')}</tbody></table>${setbackSource(r)}<p>${esc(r.catalog?.articles||'Sem validação normativa automática.')} ${esc(r.warnings.join(' '))}</p>${c.envelope.method==='conservative_uniform'?`<p>Aproximação geométrica: recuo uniforme de ${number(c.envelope.uniform,2)} m no térreo; terreno côncavo ou fundos não definidos. A maior porção contínua limita a massa.</p>`:''}<p>Área após recuos no térreo: ${number(c.setbackArea,2)} m². No último pavimento: ${number(c.topSetbackArea,2)} m². Os recuos não confirmam uso permitido, CA, taxa de ocupação, gabarito ou aprovação da construção.</p></div>`;
}
document.addEventListener('submit',event=>{
 if(!['setback-rule-form','dialog-setback-rule-form'].includes(event.target.id))return;
 event.preventDefault();const values=new FormData(event.target),g=getLotGeometry(),context={mode:values.get('mode'),zone:values.get('zone'),coastal:values.get('coastal'),regime:values.get('regime'),catalogId:SetbackRules.catalog.id,reference:String(values.get('reference')||'').trim(),url:String(values.get('url')||'').trim(),streetEdges:[g.front],roads:{}};
 for(const key of ['front','side','back'])context[key]=ParcelGeometry.num(values.get(key));
 for(let i=0;i<g.vertices.length;i++){if(values.has('street-'+i)&&i!==g.front)context.streetEdges.push(i);context.roads[i]=values.get('road-'+i)||'urban'}
 const previous=state.lot.urbanContext;state.lot.urbanContext=context;
 const result=SetbackRules.resolve(state.lot,state,g);
 if(context.mode==='manual'&&!result.resolved){state.lot.urbanContext=previous;const node=event.target.querySelector('[role=status]');node.textContent=result.reason;node.setAttribute('role','alert');return}
 context.ruleSnapshot=result;
 closeModal();render();focusMain();notify(result.resolved?'Recuos aplicados ao cálculo e ao modelo 3D. Salve o estudo para guardar o enquadramento.':'Enquadramento salvo como pendente. O 3D mantém uma prévia de demonstração.');
});
